3463: * g_date_time_format_iso8601:
3464- * @datetime: A #GDateTime
3465- *
3466- * Format @datetime in [ISO 8601 format](https://en.wikipedia.org/wiki/ISO_8601),
3467- * including the date, time and time zone, and return that as a UTF-8 encoded
3468- * string.
3469- *
3470- * Since GLib 2.66, this will output to sub-second precision if needed.
3471- *
3472- * Returns: (transfer full) (nullable): a newly allocated string formatted in
3473- *   ISO 8601 format or %NULL in the case that there was an error. The string
3474- *   should be freed with g_free().
3475- *
3476- * Since: 2.62
3477- */
3478-gchar *
3479:g_date_time_format_iso8601 (GDateTime *datetime)
3480-{
3481-  GString *outstr = NULL;
3482-  gchar *main_date = NULL;
3483-  gint64 offset;
3484-  gchar *format = "%Y-%m-%dT%H:%M:%S";
3485-
3486-  /* if datetime has sub-second non-zero values below the second precision we
3487-   * should print them as well */
3488-  if (datetime->usec % G_TIME_SPAN_SECOND != 0)
3489-    format = "%Y-%m-%dT%H:%M:%S.%f";
3490-
3491-  /* Main date and time. */
3492-  main_date = g_date_time_format (datetime, format);
3493-  outstr = g_string_new (main_date);
3494-  g_free (main_date);
3495-
3496-  /* Timezone. Format it as `%:::z` unless the offset is zero, in which case
3497-   * we can simply use `Z`. */
3498-  offset = g_date_time_get_utc_offset (datetime);
3499-
3500-  if (offset == 0)
3501-    {
3502-      g_string_append_c (outstr, 'Z');
3503-    }
3504-  else
3505-    {
3506-      gchar *time_zone = g_date_time_format (datetime, "%:::z");
3507-      g_string_append (outstr, time_zone);
3508-      g_free (time_zone);
3509-    }
3510-
3511-  return g_string_free (outstr, FALSE);
3512-}
